{
  "name": "Cytomat 自动化培养箱式微孔板存储系统",
  "name_en": "Cytomat automated incubator microplate storage system",
  "manufacturer": "Thermo Scientific",
  "description": "Cytomat 是用于微孔板（如 MTP/深孔板）自动存取与培养的培养箱式存储设备，通常带有内部仓位/货架、对外传递工位与自动门机构，可在受控温度及气体环境（如 CO₂、O₂、湿度）下存放实验板，并通过内部搬运机构在存储位、等待位与对外暴露/传递位置之间转运，便于与机械臂或自动化产线联机进行细胞培养、反应孵育与样品暂存。",
  "description_en": "Cytomat is an incubator-style automated microplate storage system for storing and handling microplates (e.g., MTP/deep-well plates). It typically provides internal rack locations, an external transfer station, and an automated door mechanism, maintaining controlled incubation conditions (e.g., temperature, CO₂, O₂, humidity). An internal transport mechanism moves plates between storage, wait, and exposed/transfer positions for integration with robotic arms and automation workflows in cell culture, incubation steps, and plate staging.",
  "actions": [
    {
      "action_name": "auto-setup",
      "description": "准备/启动设备以进入可用状态（上电后通信与基础准备）。",
      "description_en": "Set up the instrument to reach a ready state (basic startup/communication preparation)."
    },
    {
      "action_name": "auto-set_racks",
      "description": "定义/设置设备内部货架或仓位配置。",
      "description_en": "Define/set the internal rack or storage layout."
    },
    {
      "action_name": "auto-stop",
      "description": "停止设备当前任务/运行。",
      "description_en": "Stop the instrument's current task/operation."
    },
    {
      "action_name": "auto-send_command",
      "description": "向设备发送一条低层命令。",
      "description_en": "Send a low-level command to the instrument."
    },
    {
      "action_name": "auto-send_action",
      "description": "向设备发送一条动作命令并等待执行完成。",
      "description_en": "Send an action command to the instrument and wait for completion."
    },
    {
      "action_name": "auto-get_overview_register",
      "description": "获取设备总览状态寄存器。",
      "description_en": "Get the instrument overview status register."
    },
    {
      "action_name": "auto-get_warning_register",
      "description": "获取设备警告寄存器。",
      "description_en": "Get the instrument warning register."
    },
    {
      "action_name": "auto-get_error_register",
      "description": "获取设备错误寄存器。",
      "description_en": "Get the instrument error register."
    },
    {
      "action_name": "auto-reset_error_register",
      "description": "清除/复位设备错误寄存器。",
      "description_en": "Clear/reset the instrument error register."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化设备机械与内部状态。",
      "description_en": "Initialize the instrument mechanics and internal state."
    },
    {
      "action_name": "auto-open_door",
      "description": "打开设备对外门/传递口门。",
      "description_en": "Open the instrument door/transfer-port door."
    },
    {
      "action_name": "auto-close_door",
      "description": "关闭设备对外门/传递口门。",
      "description_en": "Close the instrument door/transfer-port door."
    },
    {
      "action_name": "auto-shovel_in",
      "description": "收回板托/推板机构（将搬运机构移入设备内部）。",
      "description_en": "Retract the plate shuttle/pusher mechanism (move it into the instrument)."
    },
    {
      "action_name": "auto-shovel_out",
      "description": "伸出板托/推板机构（将搬运机构移向对外取放位置）。",
      "description_en": "Extend the plate shuttle/pusher mechanism (move it toward the external access position)."
    },
    {
      "action_name": "auto-get_action_register",
      "description": "获取设备动作状态寄存器。",
      "description_en": "Get the instrument action status register."
    },
    {
      "action_name": "auto-get_swap_register",
      "description": "获取设备交换/转运相关状态寄存器。",
      "description_en": "Get the instrument swap/transfer-related status register."
    },
    {
      "action_name": "auto-get_sensor_register",
      "description": "获取设备传感器状态寄存器。",
      "description_en": "Get the instrument sensor status register."
    },
    {
      "action_name": "auto-action_transfer_to_storage",
      "description": "将微孔板从传递工位取入并放回指定存储位。",
      "description_en": "Pick a microplate from the transfer station and place it into the specified storage site."
    },
    {
      "action_name": "auto-action_storage_to_transfer",
      "description": "将微孔板从指定存储位取出并送至传递工位。",
      "description_en": "Retrieve a microplate from the specified storage site and deliver it to the transfer station."
    },
    {
      "action_name": "auto-action_storage_to_wait",
      "description": "将微孔板从指定存储位取出并移动到等待位置。",
      "description_en": "Retrieve a microplate from the specified storage site and move it to the wait position."
    },
    {
      "action_name": "auto-action_wait_to_storage",
      "description": "将微孔板从等待位置送回指定存储位并卸载。",
      "description_en": "Move a microplate from the wait position back into the specified storage site and unload it."
    },
    {
      "action_name": "auto-action_wait_to_transfer",
      "description": "将微孔板从等待位置送至传递工位（用于外部取放）。",
      "description_en": "Move a microplate from the wait position to the transfer station for external pickup/placement."
    },
    {
      "action_name": "auto-action_transfer_to_wait",
      "description": "将微孔板从传递工位取回并返回等待位置。",
      "description_en": "Pick a microplate from the transfer station and return it to the wait position."
    },
    {
      "action_name": "auto-action_wait_to_exposed",
      "description": "将微孔板从等待位置移动到设备外部暴露位置。",
      "description_en": "Move a microplate from the wait position to an exposed position outside the instrument."
    },
    {
      "action_name": "auto-action_exposed_to_wait",
      "description": "将微孔板从外部暴露位置收回到等待位置。",
      "description_en": "Return a microplate from the exposed external position to the wait position."
    },
    {
      "action_name": "auto-action_exposed_to_storage",
      "description": "将微孔板从外部暴露位置收回并放入指定存储位。",
      "description_en": "Return a microplate from the exposed external position and place it into the specified storage site."
    },
    {
      "action_name": "auto-action_storage_to_exposed",
      "description": "将微孔板从指定存储位取出并送到设备外部暴露位置。",
      "description_en": "Retrieve a microplate from the specified storage site and move it to an exposed position outside the instrument."
    },
    {
      "action_name": "auto-action_read_barcode",
      "description": "读取指定存储位置的条码信息（用于板/位置识别）。",
      "description_en": "Read barcode information for specified storage locations (for plate/location identification)."
    },
    {
      "action_name": "auto-wait_for_transfer_station",
      "description": "等待传递工位变为占用或空闲状态。",
      "description_en": "Wait until the transfer station becomes occupied or unoccupied."
    },
    {
      "action_name": "auto-wait_for_task_completion",
      "description": "等待设备当前任务执行完成（直到不再忙碌）。",
      "description_en": "Wait for the instrument to finish the current task (until it is no longer busy)."
    },
    {
      "action_name": "auto-init_shakers",
      "description": "初始化设备内置振荡/摇床模块。",
      "description_en": "Initialize the instrument’s internal shaker modules."
    },
    {
      "action_name": "auto-start_shaking",
      "description": "开始振荡/摇床运行（按给定频率）。",
      "description_en": "Start shaking operation (at the specified frequency)."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡/摇床运行。",
      "description_en": "Stop shaking operation."
    },
    {
      "action_name": "auto-set_shaking_frequency",
      "description": "设置振荡/摇床频率。",
      "description_en": "Set the shaker frequency."
    },
    {
      "action_name": "auto-get_incubation_query",
      "description": "获取培养相关查询项的状态/读数。",
      "description_en": "Get the value/status for an incubation-related query item."
    },
    {
      "action_name": "auto-get_co2",
      "description": "获取 CO₂ 浓度读数。",
      "description_en": "Get the CO₂ concentration reading."
    },
    {
      "action_name": "auto-get_humidity",
      "description": "获取湿度读数。",
      "description_en": "Get the humidity reading."
    },
    {
      "action_name": "auto-get_o2",
      "description": "获取 O₂ 浓度读数。",
      "description_en": "Get the O₂ concentration reading."
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取温度读数。",
      "description_en": "Get the temperature reading."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置温度设定值。",
      "description_en": "Set the temperature setpoint."
    },
    {
      "action_name": "auto-fetch_plate_to_loading_tray",
      "description": "将指定微孔板取出并送至装载托盘/装载位。",
      "description_en": "Fetch the specified microplate and place it onto the loading tray/loading position."
    },
    {
      "action_name": "auto-take_in_plate",
      "description": "将微孔板收入设备并放入指定存储位。",
      "description_en": "Take a microplate into the instrument and place it into the specified storage site."
    },
    {
      "action_name": "auto-serialize",
      "description": "导出/记录设备当前配置或状态信息。",
      "description_en": "Export/record the instrument’s current configuration or state information."
    }
